// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this));
        amount = bound(amount, 0, type(uint256).max);
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // Universal rule: a non-owner withdraw attempt must fail and never drain the contract.
        assertTrue(!ok && address(c).balance == amount);
    }
}
